 logic [1:0] a_mux_sel_w;
 logic [1:0] b_mux_sel_w;
 logic cen_w;
 logic rst_w;
 logic stack_push_w;
 logic stack_pop_w;
 logic pc_mux_sel_w;
 logic stack_mux_sel_w;
 logic stack_we_w;
 logic stack_re_w;
 logic inc_w;
 logic oen_w;
 logic out_en_w;

 lifo_stack dut_1 (
    .clk              (clk),
    .stack_data_1_in  (d_in),
    .stack_data_2_in  (pc_data_w),
    .stack_reset      (rst_w),
    .stack_push       (stack_push_w),
    .stack_pop        (stack_pop_w),
    .stack_mux_sel    (stack_mux_sel_w),
    .stack_we         (stack_we_w),
    .stack_re         (stack_re_w),
    .stack_data_out   (stack_data_w),
    .full_o           (full),
    .empty_o          (empty)
 );

 program_counter dut_2 (
    .clk               (clk),
    .full_adder_data_i (fa_out_w),
    .pc_c_in           (c_inc_in),
    .inc               (inc_w),
    .pc_mux_sel        (pc_mux_sel_w),
    .pc_out            (pc_data_w),
    .pc_c_out          (c_inc_out),
    .pc_g_out          (g_inc_out),
    .pc_p_out          (p_inc_out)
 );

 microcode_arithmetic dut_3(
    .clk              (clk),
    .fa_in            (data_out_w),
    .d_in             (d_in),
    .stack_data_in    (stack_data_w),
    .pc_data_in       (pc_data_w),
    .reg_en           (r_en),
    .oen              (oen_w),
    .rsel             (rsel_w),
    .rce              (rce_w),
    .cen              (cen_w),
    .a_mux_sel        (a_mux_sel_w),
    .b_mux_sel        (b_mux_sel_w),
    .arith_cin        (c_n_in),
