    .pc_mux_sel       (pc_mux_sel_w), 
    .a_mux_sel        (a_mux_sel_w), 
    .b_mux_sel        (b_mux_sel_w), 
    .push             (stack_push_w),
    .pop              (stack_pop_w), 
