module instruction_decoder(
    input logic [4:0] instr_in,
    input logic cc_in,
    input logic instr_en,
    output logic cen, 
    output logic rst, 
    output logic oen, 
    output logic inc, 
    output logic rsel, 
    output logic rce,  
    output logic pc_mux_sel, 
    output logic [1:0] a_mux_sel, 
    output logic [1:0] b_mux_sel, 
    output logic push,
    output logic pop, 
