);

logic [3:0] fa_out_w;
logic [3:0] reg_mux_out_w;
logic [3:0] reg_out_w;
logic [3:0] a_mux_out_w;
logic [3:0] b_mux_out_w;


aux_reg_mux dut_1 (
  .reg1_in     (fa_in),
  .reg2_in     (d_in),
  .rsel        (rsel),
  .re          (reg_en),
  .reg_mux_out (reg_mux_out_w)
);

aux_reg dut_2 (
    .clk     (clk),
    .reg_in  (reg_mux_out_w),
