                     oen         = 1'b1; 
                     pc_mux_sel  = 1'b1; 
                     inc         = 1'b1; 
                     src_sel     = 1'b0;
                     push        = 1'b0;
                     stack_we    = 1'b0;
                  end
     7'b00100x0 : begin 
                     rst         = 1'b0;
