                                 ( encoder_in_w[0] &  encoder_in_w[1] & !encoder_in_w[2] & !encoder_in_w[3]) |
                                 ( encoder_in_w[0] & !encoder_in_w[1] &  encoder_in_w[2] & !encoder_in_w[3]) |
                                 ( encoder_in_w[0] & !encoder_in_w[1] & !encoder_in_w[2] &  encoder_in_w[3]) |
                                 (!encoder_in_w[0] &  encoder_in_w[1] & !encoder_in_w[2] &  encoder_in_w[3]);
    assign is_three_high       = ( encoder_in_w[0] &  encoder_in_w[1] &  encoder_in_w[2] & !encoder_in_w[3]) |
                                 ( encoder_in_w[0] &  encoder_in_w[1] & !encoder_in_w[2] &  encoder_in_w[3]) |
                                 ( encoder_in_w[0] & !encoder_in_w[1] &  encoder_in_w[2] &  encoder_in_w[3]) |
