    assign disp5 = (encoder_in_w[5] & encoder_in_w[6]);
    assign disp6 = ((encoder_in_w[5] ^ encoder_in_w[6])) | K;
    assign invert_fj = !(rd1 ? disp5 : (disp4 | disp6));

    always_comb begin
        f_w = ((encoder_in_w[5] & encoder_in_w[6] & encoder_in_w[7] & SorK) ? 1'b1 : !encoder_in_w[5]);
