                    else begin
                        if (i_temp_feedback[3]) begin 
                            next_state = HEAT_LOW; 
                        end// Low cold
                        else if (i_temp_feedback[2]) begin // Low hot
                            next_state = COOL_LOW;
                        end
                        else begin
                            next_state = AMBIENT;
                        end
                    end
                end
            end

            // Ambient state
            AMBIENT: begin
                heater_full = 0;
                heater_medium = 0;
                heater_low = 0;
                aircon_full = 0;
                aircon_medium = 0;
                aircon_low = 0;
                fan = 0;
                if (i_temp_feedback[5]) begin 
                    next_state = HEAT_FULL; 
                end// Full cold
                else if (i_temp_feedback[0]) begin // Full hot
                    next_state = COOL_FULL;
                end
                else begin
                    if (i_temp_feedback[4]) begin 
                        next_state = HEAT_MED; 
                    end// Medium cold
                    else if (i_temp_feedback[1]) begin // Medium hot
                        next_state = COOL_MED;
                    end
                    else begin
                        if (i_temp_feedback[3]) begin 
                            next_state = HEAT_LOW; 
                        end// Low cold
                        else if (i_temp_feedback[2]) begin // Low hot
                            next_state = COOL_LOW;
                        end
                        else begin
                            next_state = AMBIENT;
                        end
                    end
                end
            end

            default: next_state = AMBIENT; // Safety fallback
        endcase
    end
end

