`timescale 1ns / 1ps

module lfsr_8bit (
    input clock,
    input reset,
    input [7:0] lfsr_seed,
    input sel,  // Selector for NAND or NOR operation (0: NOR for more 0s, 1: NAND for more 1s)
    input dir,  // Direction control (0: LSB to MSB, 1: MSB to LSB)
    input [2:0] weight,  // Weight control signal
    output reg [7:0] lfsr_new

);
  wire q1;
  wire q2;
  wire q3;
  reg [7:0] output_new;
  reg [7:0] lfsr_out;

  // Primitive polynomial for 8-bit LFSR with Galois configuration: x^8 + x^6 + x^5 + x + 1
  assign q1 = lfsr_out[6] ^ lfsr_out[0];
  assign q2 = lfsr_out[5] ^ lfsr_out[0];
  assign q3 = lfsr_out[1] ^ lfsr_out[0];

  // Enhanced Weighted Feedback Logic based on selector (sel) and direction (dir)
  //wire nand_result, nor_result;
  //assign nand_result = dir ? ~(lfsr_out[7] & lfsr_out[6] & lfsr_out[5]) : ~(lfsr_out[2] & lfsr_out[1] & lfsr_out[0]);
  //assign nor_result  = dir ? ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5]) : ~(lfsr_out[2] | lfsr_out[1] | lfsr_out[0]);

  // Select between NAND or NOR based on 'sel' signal
  //wire weighted_out = sel ? nand_result : nor_result;

  always @* begin
    output_new = lfsr_out;  // Default to no change

    // Apply feedback logic based on the selected direction and NAND/NOR operation
    if (sel == 0 && dir == 0) begin  // LSB to MSB, NOR
