        3'b000: output_new = lfsr_out;  // No change
        3'b001: output_new = {lfsr_out[7:1], ~(lfsr_out[0] | 1'b1)};
        3'b010:
        output_new = {output_new[7:2], ~(lfsr_out[1] | lfsr_out[0]), ~(lfsr_out[1] | lfsr_out[0])};
        3'b011:
        output_new = {
          lfsr_out[7:3],
          ~(lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[2] | lfsr_out[1] | lfsr_out[0])
        };
        3'b100:
        output_new = {
