          ~(lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0])
        };
        3'b101:
        output_new = {
          lfsr_out[7:5],
          ~(lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0])
        };
        3'b110:
        output_new = {
          output_new[7:6],
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2])
        };
        3'b111:
        output_new = {
          output_new[7],
          ~(lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
          ~(lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1] | lfsr_out[0]),
