          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4]),
          lfsr_out[7:4]
        };
        3'b101:
        output_new = {
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3]),
