          lfsr_out[7:5]
        };
        3'b110:
        output_new = {
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2]),
          lfsr_out[7:6]
        };
        3'b111:
        output_new = {
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1]),
          ~(lfsr_out[7] | lfsr_out[6] | lfsr_out[5] | lfsr_out[4] | lfsr_out[3] | lfsr_out[2] | lfsr_out[1]),
