// ----- direct_map_cache.sv -----
module direct_map_cache #(
    parameter CACHE_SIZE = 256,                 // Number of cache lines
    parameter DATA_WIDTH = 16,                  // Width of data
    parameter TAG_WIDTH = 5,                    // Width of the tag
    parameter OFFSET_WIDTH = 3,                 // Width of the offset
    localparam INDEX_WIDTH = $clog2(CACHE_SIZE) // Width of the index
) (
    input wire enable,                          // Enable signal
    input wire [INDEX_WIDTH-1:0] index,         // Cache index
    input wire [OFFSET_WIDTH-1:0] offset,       // Byte offset within the cache line
    input wire comp,                            // Compare operation signal
    input wire write,                           // Write operation signal
    input wire [TAG_WIDTH-1:0] tag_in,          // Input tag for comparison and writing
    input wire [DATA_WIDTH-1:0] data_in,        // Input data to be written
    input wire valid_in,                        // Valid state for cache line
    input wire clk,                             // Clock signal
    input wire rst,                             // Reset signal (active high)
    output reg hit,                             // Hit indication
    output reg dirty,                           // Dirty state indication
    output reg [TAG_WIDTH-1:0] tag_out,         // Output tag of the cache line
    output reg [DATA_WIDTH-1:0] data_out,       // Output data from the cache line
    output reg valid,                           // Valid state output
    output reg error                            // Error indication for invalid accesses
);

    // Cache line definitions
    reg [TAG_WIDTH-1:0] tags [CACHE_SIZE-1:0];                       // Tag storage
    reg [DATA_WIDTH-1:0] data_mem [CACHE_SIZE-1:0][OFFSET_WIDTH:0];  // Data storage
    reg valid_bits [CACHE_SIZE-1:0];                                 // Valid bits for each line
    reg dirty_bits [CACHE_SIZE-1:0];                                 // Dirty bits for each line
    integer i;

    // Sequential logic for cache operations
    always @(posedge clk) begin
        if (rst) begin
            // Initialize cache lines on reset
            for (i = 0; i < CACHE_SIZE; i = i + 1) begin
                valid_bits[i] <= 1'b0;                       
                dirty_bits[i] <= 1'b0;                                      
            end
            hit      <= 1'b0;                                    
            dirty    <= 1'b0;                                                     
            valid    <= 1'b0;
            data_out <= {DATA_WIDTH{1'b0}};                                   
        end 
        else if (enable) begin
            // Check for LSB alignment error
            if (offset[0] == 1'b1) begin
                error <= 1'b1;                               // Set error if LSB of offset is 1
                hit   <= 1'b0;                                 
                dirty <= 1'b0;                               
                valid <= 1'b0;                               
                data_out <= {DATA_WIDTH{1'b0}};              
            end 
            else begin
                error <= 1'b0;                               // Clear error if LSB of offset is 0

                // Compare operation
                if (comp) begin
                    // Compare Write (comp = 1, write = 1) 
                    if (write) begin
                        if ((tags[index] == tag_in) && valid_bits[index]) begin
                            hit <= 1'b1;
                            data_mem[index][offset[OFFSET_WIDTH-1:1]] <= data_in; 
                            dirty_bits[index] <= 1'b1;  
                            valid_bits[index] <= valid_in; 
                            valid    <= 1'b0;                 
                            dirty    <= 1'b0; 

                        end
                        else begin
                            hit <= 1'b0;
                            dirty_bits[index] <= 1'b0;
                            valid_bits[index] <= valid_in;
                            tags[index]       <= tag_in;
                            valid    <= 1'b0;                 
                            dirty    <= 1'b0;  
                            data_mem[index][offset[OFFSET_WIDTH-1:1]] <= data_in;              
                        end
                    end 
                    else begin // Write
                        // Compare Read (comp = 1, write = 0)
                        if ((tags[index] == tag_in) && valid_bits[index]) begin
                            hit <= 1'b1;
                            data_out <= data_mem[index][offset[OFFSET_WIDTH-1:1]]; 
                            valid    <= valid_bits[index];                 
                            dirty    <= dirty_bits[index]; 
                            tag_out  <= tags[index];                
                        end
                        else begin
                            hit <= 1'b0;
                            tag_out  <= tags[index];
                            valid <= valid_bits[index];                   
                            dirty <= dirty_bits[index]; 
                            data_out <= data_mem[index][offset[OFFSET_WIDTH-1:1]];                 
                        end
                    end
                end 
                else begin //compare
                    if (write) begin
                        // Access Write (comp = 0, write = 1)
                        tags[index]       <= tag_in;                       
                        data_mem[index][offset[OFFSET_WIDTH-1:1]] <= data_in; 
                        valid_bits[index] <= valid_in;               
                        dirty_bits[index] <= 1'b0;
                        hit      <= 1'b0;
                        valid    <= 1'b0;                 
                        dirty    <= 1'b0;

                    end 
                    else begin
                        // Access Read (comp = 0, write = 0)
                        tag_out  <= tags[index];                      
                        data_out <= data_mem[index][offset[OFFSET_WIDTH-1:1]]; 
                        valid    <= valid_bits[index];                  
                        dirty    <= dirty_bits[index];
                        hit      <= 1'b0;

                    end
                end
            end 
        end 
        else begin // enable
            // enable is low
            for (i = 0; i < CACHE_SIZE; i = i + 1) begin
                valid_bits[i] <= 1'b0;                           
                dirty_bits[i] <= 1'b0;                                                  
            end

            hit      <= 1'b0;                                       
            dirty    <= 1'b0;                                                         
            data_out <= {DATA_WIDTH{1'b0}};                    
            valid    <= 1'b0;                                     
        end
    end

endmodule

// ----- enhanced_fsm_signal_processor.v -----
// Verilog RTL Design for enhanced_fsm_signal_processor

module enhanced_fsm_signal_processor (
    input wire i_clk,            // Clock signal
    input wire i_rst_n,          // Active-low reset signal
    input wire i_enable,         // Enable signal to start processing
    input wire i_clear,          // Signal to clear fault state and reset outputs
    input wire i_ack,            // Acknowledge signal to transition from READY to IDLE
    input wire i_fault,          // Fault condition signal
    input wire [4:0] i_vector_1, // Input vector 1
    input wire [4:0] i_vector_2, // Input vector 2
    input wire [4:0] i_vector_3, // Input vector 3
    input wire [4:0] i_vector_4, // Input vector 4
    input wire [4:0] i_vector_5, // Input vector 5
    input wire [4:0] i_vector_6, // Input vector 6

    output reg o_ready,          // Indicates when processing is complete
    output reg o_error,          // Indicates fault condition
    output reg [1:0] o_fsm_status, // Current FSM state
    output reg [7:0] o_vector_1, // Processed output vector 1
    output reg [7:0] o_vector_2, // Processed output vector 2
    output reg [7:0] o_vector_3, // Processed output vector 3
    output reg [7:0] o_vector_4  // Processed output vector 4
);

// FSM state definitions
localparam IDLE   = 2'b00;
localparam PROCESS = 2'b01;
localparam READY   = 2'b10;
localparam FAULT   = 2'b11;

// Internal registers
reg [1:0] current_state, next_state;
reg [31:0] concatenated_vector;

// Synchronous state transition and reset handling
always @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
        current_state <= IDLE;   // Reset state to IDLE
    end else begin
        current_state <= next_state;
    end
end

// Next state logic
always @(*) begin
    case (current_state)
        IDLE: begin
            if (i_fault) begin
                next_state = FAULT;
            end 
            else begin
                if (i_enable) begin
                next_state = PROCESS;
                end
                else next_state = current_state;
            end
        end
        PROCESS: begin
            if (i_fault) begin
                next_state = FAULT;
            end else begin
                next_state = READY;
            end
        end
        READY: begin
            if (i_fault) begin
                next_state = FAULT;
            end 
            else begin
                if (i_ack) begin
                    next_state = IDLE;
                end
                else next_state = current_state;
            end
        end
        FAULT: begin
            if (i_clear && !i_fault) begin
                next_state = IDLE;
            end
            else next_state = current_state;
        end
    endcase
end

// Output logic and processing
always @(posedge i_clk or negedge i_rst_n) begin
    if (!i_rst_n) begin
        o_ready <= 0;
        o_error <= 0;
        o_fsm_status <= IDLE;
        o_vector_1 <= 0;
        o_vector_2 <= 0;
        o_vector_3 <= 0;
        o_vector_4 <= 0;
        concatenated_vector <= 0;
    end else begin
        o_fsm_status <= current_state;  // Update FSM status
        case (current_state)
            IDLE: begin
                o_ready <= 0;
                o_error <= 0;
                o_vector_1 <= 0;
                o_vector_2 <= 0;
                o_vector_3 <= 0;
                o_vector_4 <= 0;
            end
            PROCESS: begin
                concatenated_vector <= {i_vector_1, i_vector_2, i_vector_3, i_vector_4, i_vector_5, i_vector_6, 2'b11};
                end
            READY: begin
                o_vector_1 <= concatenated_vector[31:24]; // MSB
                o_vector_2 <= concatenated_vector[23:16];
                o_vector_3 <= concatenated_vector[15:8];
                o_vector_4 <= concatenated_vector[7:0];  // LSB
                o_ready <= 1;
            end
            FAULT: begin
                o_error <= 1;
                o_ready <= 0;
                o_vector_1 <= 0;
                o_vector_2 <= 0;
                o_vector_3 <= 0;
                o_vector_4 <= 0;
            end
        endcase
