    for (genvar i = 0; i < N-1; i++) begin
      // Port[0] highest priority
      assign priority_req[i+1] = priority_req[i] | req_i[i];
    end
  end

  // -------------------------------------------------------
  // Output assignments
  // --------------------------------------------------------
  assign gnt_o[N-1:0] = req_i[N-1:0] & ~priority_req[N-1:0];

endmodule

