    // DUT Inputs
    reg clk;
    reg reset;
    reg signed [15:0] in_1;
    reg signed [15:0] in_2;
    reg signed [15:0] in_3;
    reg [1:0] filter_select;

    // DUT Outputs
    wire signed [15:0] out_1;
    wire signed [15:0] out_2;
    wire signed [15:0] out_3;

    // Instantiate the DUT
    iir_filt #(.WIDTH(16)) uut (
        .clk(clk),
        .reset(reset),
        .in_1(in_1),
        .in_2(in_2),
        .in_3(in_3),
        .filter_select(filter_select),
        .out_1(out_1),
        .out_2(out_2),
        .out_3(out_3)
    );

    // Clock generation
    initial clk = 0;
    always #5 clk = ~clk; // 100 MHz clock

    // Test procedure
    initial begin
        // Initialize inputs
        reset = 1;
        #20;
        reset = 0;
        $display("[%0t] DUT reset completed", $time);

        // Edge case testing
        $display("[%0t] Starting edge case testing", $time);
        in_1 = 16'h7FFF; in_2 = 16'h8000; in_3 = 16'h7FFF; filter_select = 2'b00; #20;
