                grant <= 8'b00010000;
            else if (req[5])
                grant <= 8'b00100000;
            else if (req[6])
                grant <= 8'b01000000;
            else if (req[7])
                grant <= 8'b10000000;
            else
                grant <= 8'b00000000;
        end
    end
